using Berbergelsin.Api.Auth;using Berbergelsin.Api.Data;using Berbergelsin.Api.Dtos;using Berbergelsin.Api.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace Berbergelsin.Api.Controllers;
[ApiController,Authorize(Roles="Musteri,Berber")]
public sealed class RatingsController(AppDbContext db,IConfiguration config):ControllerBase
{
 [HttpPut("api/ratings/{id:guid}")]
 public async Task<IActionResult> Update(Guid id,UpdateRatingRequest req,CancellationToken ct){if(req.Score is<1 or>5||req.Comment?.Trim().Length>600||!Guid.TryParse(req.Version,out var version))return Error(400,"rating_invalid");var uid=User.GetUserId();var r=await db.Ratings.Include(x=>x.RaterUser).SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted,ct);if(r==null)return Error(404,"rating_not_found");if(r.RaterUserId!=uid)return Error(403,"rating_forbidden");if(r.ModerationStatus!=RatingModerationStatus.Visible)return Error(409,"rating_locked");if(DateTime.UtcNow-r.CreatedAt>TimeSpan.FromHours(config.GetValue("Ratings:EditWindowHours",720)))return Error(409,"rating_edit_window_expired");if(r.Version!=version)return Error(409,"rating_conflict");r.Score=req.Score;r.Comment=string.IsNullOrWhiteSpace(req.Comment)?null:req.Comment.Trim();r.UpdatedAt=DateTime.UtcNow;r.Version=Guid.NewGuid();try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Error(409,"rating_conflict");}return Ok(ToClient(r,null));}
 [HttpDelete("api/ratings/{id:guid}")]
 public async Task<IActionResult> Delete(Guid id,CancellationToken ct){var uid=User.GetUserId();var r=await db.Ratings.Include(x=>x.RaterUser).SingleOrDefaultAsync(x=>x.Id==id,ct);if(r==null)return Error(404,"rating_not_found");if(r.RaterUserId!=uid)return Error(403,"rating_forbidden");if(!r.IsDeleted){r.IsDeleted=true;r.DeletedAt=DateTime.UtcNow;r.DeletedByUserId=uid;r.Version=Guid.NewGuid();await db.SaveChangesAsync(ct);}return Ok(new{id,deleted=true});}
 [HttpGet("api/client/ratings")]
 public async Task<IActionResult> Mine([FromQuery]int page=1,[FromQuery]int pageSize=20,CancellationToken ct=default){if(page<1||pageSize<1||pageSize>50)return Error(400,"rating_invalid");var uid=User.GetUserId();var q=db.Ratings.AsNoTracking().Where(r=>r.RaterUserId==uid&&!r.IsDeleted);var total=await q.CountAsync(ct);var items=await q.OrderByDescending(r=>r.CreatedAt).ThenBy(r=>r.Id).Skip((page-1)*pageSize).Take(pageSize).Select(r=>new ClientRatingDto(r.Id,r.ServiceRequestId,r.ServiceRequest.BarberProfileId,r.ServiceRequest.BarberProfile.BusinessName,r.Score,r.Comment,r.CreatedAt,r.UpdatedAt,r.ModerationStatus.ToString(),r.Version.ToString())).ToListAsync(ct);return Ok(new ClientRatingsPageDto(items,page,pageSize,total,page*pageSize<total));}
 [HttpPost("api/ratings/{id:guid}/report")]
 public async Task<IActionResult> Report(Guid id,ReportRatingRequest req,CancellationToken ct){var reasons=new[]{"spam","abuse","personal_data","false_information","other"};if(!reasons.Contains(req.ReasonCode)||req.Description?.Trim().Length>500)return Error(400,"rating_report_invalid");var uid=User.GetUserId();var r=await db.Ratings.SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted&&x.ModerationStatus==RatingModerationStatus.Visible,ct);if(r==null)return Error(404,"rating_not_found");if(r.RaterUserId==uid)return Error(403,"rating_forbidden");if(await db.RatingReports.AnyAsync(x=>x.RatingId==id&&x.ReporterUserId==uid&&x.ReasonCode==req.ReasonCode,ct))return Error(409,"rating_conflict");db.RatingReports.Add(new(){Id=Guid.NewGuid(),RatingId=id,ReporterUserId=uid,ReasonCode=req.ReasonCode,Description=string.IsNullOrWhiteSpace(req.Description)?null:req.Description.Trim(),CreatedAt=DateTime.UtcNow});try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){return Error(409,"rating_conflict");}return Ok(new{ratingId=id,reported=true});}
 static ClientRatingDto ToClient(Entities.Rating r,string? name)=>new(r.Id,r.ServiceRequestId,r.ServiceRequest?.BarberProfileId??Guid.Empty,name,r.Score,r.Comment,r.CreatedAt,r.UpdatedAt,r.ModerationStatus.ToString(),r.Version.ToString());
 ObjectResult Error(int status,string code)=>StatusCode(status,new{code});
}
